test:
result = replay_billing_transactions(('balance', 'credit'), {
    'z-later': {'user_id': 'ada', 'timestamp': 3, 'balance': 4},
    'b-tie': {'user_id': 'ada', 'timestamp': 1, 'balance': 2},
    'a-tie': {'user_id': 'ada', 'timestamp': 1, 'balance': 5, 'overwrite': True},
    'only-command': {'user_id': 'lin', 'timestamp': 2, 'undo_last': True},
})
assert result == {'ada': {'balance': 11, 'credit': 0}, 'lin': {'balance': 0, 'credit': 0}}

result = replay_billing_transactions(('balance', 'credit'), {
    'one': {'user_id': 'u', 'timestamp': 1, 'balance': 10, 'credit': 2},
    'two': {'user_id': 'u', 'timestamp': 2, 'balance': 5, 'overwrite': True},
    'three': {'user_id': 'u', 'timestamp': 3, 'undo_last': True, 'credit': 999},
    'four': {'user_id': 'u', 'timestamp': 4, 'redo_last': True},
    'five': {'user_id': 'u', 'timestamp': 5, 'undo_last': True},
    'six': {'user_id': 'u', 'timestamp': 6, 'credit': 7},
    'seven': {'user_id': 'u', 'timestamp': 7, 'redo_last': True},
})
assert result == {'u': {'balance': 10, 'credit': 9}}

result = replay_billing_transactions(('x',), {
    'a1': {'user_id': 'a', 'timestamp': 1, 'x': 4},
    'b1': {'user_id': 'b', 'timestamp': 1, 'x': 9},
    'a2': {'user_id': 'a', 'timestamp': 2, 'undo_last': True},
    'a3': {'user_id': 'a', 'timestamp': 3},
    'a4': {'user_id': 'a', 'timestamp': 4, 'redo_last': True},
    'b2': {'user_id': 'b', 'timestamp': 2, 'undo_last': True},
    'b3': {'user_id': 'b', 'timestamp': 3, 'redo_last': True},
})
assert result == {'a': {'x': 0}, 'b': {'x': 9}}
